package com.vahotel.service;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.vahotel.model.*;import com.vahotel.repo.ReservationRepository;import java.math.BigDecimal;import java.time.LocalDate;import org.junit.jupiter.api.Test;
class ReservationServiceTest {
 @Test void rejectsInvalidDateRange(){ReservationRepository repo=mock(ReservationRepository.class);ReservationService service=new ReservationService(repo);Room room=new Room("101","Standard","Test",new BigDecimal("1000"));Account customer=new Account("a@b.com","hash","A",Role.CUSTOMER,true);LocalDate checkIn=LocalDate.now(java.time.ZoneId.of("Asia/Manila")).plusDays(1);assertThrows(IllegalArgumentException.class,()->service.create(customer,room,checkIn,checkIn));verifyNoInteractions(repo);}
 @Test void allowsSameDayCheckInForWalkInsAndRejectsItForCustomerBookings(){ReservationRepository repo=mock(ReservationRepository.class);when(repo.save(any(Reservation.class))).thenAnswer(call->call.getArgument(0));ReservationService service=new ReservationService(repo);Room room=new Room("101","Standard","Test",new BigDecimal("1000"));Account customer=new Account("a@b.com","hash","A",Role.CUSTOMER,true);LocalDate today=LocalDate.now(java.time.ZoneId.of("Asia/Manila"));Reservation walkIn=service.createWalkIn(customer,room,today,today.plusDays(1));assertEquals(today,walkIn.getCheckIn());assertEquals(today.plusDays(1),walkIn.getCheckOut());assertEquals(new BigDecimal("1000"),walkIn.getTotalPrice());assertThrows(IllegalArgumentException.class,()->service.create(customer,room,today,today.plusDays(1)));verify(repo).save(any(Reservation.class));}
}
